package org.slavicmyths.verify;
import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.placement.*;import org.slavicmyths.chud.*;
import static org.slavicmyths.verify.Stabilization269.*;
/** Exact production start decisions and weighted fallback, then native FULL rare-start confirmation. */
@net.neoforged.fml.common.EventBusSubscriber(modid="slavicmyths")
final class Frequency269 {
 static final TicketType<Long> TICKET=TicketType.create("qa269_frequency",Long::compare);static final List<Map<String,Object>> rows=new ArrayList<>(),nativeRows=new ArrayList<>(),regions=new ArrayList<>();static final LinkedHashMap<String,ChunkPos> confirmations=new LinkedHashMap<>();static int index,phase,ci;static long began,waiting;static ChunkPos held;static java.util.concurrent.Future<Map<String,Object>> pending;static long pendingSince;static final java.util.concurrent.ExecutorService WORKER=java.util.concurrent.Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"qa269-native-forecast");t.setDaemon(true);t.setPriority(Thread.MIN_PRIORITY);return t;});
 @net.neoforged.bus.api.SubscribeEvent public static void stopped(net.neoforged.neoforge.event.server.ServerStoppedEvent e){if(!"frequency".equals(System.getProperty("slavicmyths.qa269")))return;try{var f=ChudKnownSites.class.getDeclaredField("KNOWN");f.setAccessible(true);var a=org.slavicmyths.worldgen.SiteChunks.class.getDeclaredField("ACTIVE");a.setAccessible(true);int known=((Map<?,?>)f.get(null)).size(),active=((Set<?>)a.get(null)).size();java.nio.file.Files.writeString(java.nio.file.Path.of("frequency-stop-cleanup.json"),new com.google.gson.Gson().toJson(Map.of("known_worlds_after_stop",known,"site_chunks_owners_after_stop",active,"status",known==0&&active==0?"PASS":"FAIL")));}catch(Exception x){throw new RuntimeException(x);}}
 static Map<String,Object> planCell(int serial){long begin=System.nanoTime();ChudSearchBudget.begin(begin+5_000_000_000L);try{String setName=new String[]{"serpent_hill","gorodishche","kurgan_small"}[serial%3];int cell=serial/3,x=cell/10-5,z=cell%10-5;var set=w.registryAccess().registryOrThrow(Registries.STRUCTURE_SET).get(id(setName));var placement=(RandomSpreadStructurePlacement)set.placement();var at=placement.getPotentialStructureChunk(w.getSeed(),x*placement.spacing(),z*placement.spacing());var row=new LinkedHashMap<String,Object>();row.put("set",setName);row.put("cell",List.of(x,z));row.put("chunk",List.of(at.x,at.z));boolean allowed=placement.isStructureChunk(w.getChunkSource().getGeneratorState(),at.x,at.z);row.put("placement_allowed",allowed);String selected=null;var attempts=new ArrayList<String>();long t=System.nanoTime();
 if(allowed){var entries=new ArrayList<>(set.structures());var random=new WorldgenRandom(new LegacyRandomSource(0));random.setLargeFeatureSeed(w.getSeed(),at.x,at.z);int weight=entries.stream().mapToInt(StructureSet.StructureSelectionEntry::weight).sum();while(!entries.isEmpty()){int draw=entries.size()==1?0:random.nextInt(weight),which=0;if(entries.size()>1){for(var entry:entries){draw-=entry.weight();if(draw<0)break;which++;}}var entry=entries.get(which);var name=entry.structure().unwrapKey().orElseThrow().location().toString();attempts.add(name);var decision=generate(entry.structure().value(),at);ChudSearchBudget.check();if(decision.isValid()){selected=name;break;}entries.remove(which);weight-=entry.weight();}}
 row.put("attempted_structures",attempts);row.put("accepted",selected);row.put("cpu_wall_ms",(System.nanoTime()-t)/1e6);return row;}catch(java.util.concurrent.CancellationException cancelled){org.slavicmyths.worldgen.StructureCoverageService.clearFootprints();ChudRegionPlanner.clear();var row=new LinkedHashMap<String,Object>();row.put("set",new String[]{"serpent_hill","gorodishche","kurgan_small"}[serial%3]);row.put("serial",serial);row.put("accepted","UNKNOWN_BUDGET");row.put("cpu_wall_ms",(System.nanoTime()-begin)/1e6);return row;}finally{ChudSearchBudget.end();}}
 static ResourceLocation id(String s){return ResourceLocation.fromNamespaceAndPath("slavicmyths",s);}
 static void init(){began=System.nanoTime();out.put("scope","3-set sampled cells; actual native generator and vanilla weighted retry; forecasts do not place blocks; rare forecasts subsequently require native FULL");}
 static StructureStart generate(Structure s,ChunkPos at){var g=w.getChunkSource().getGenerator();return s.generate(w.registryAccess(),g,g.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),at,0,w,s.biomes()::contains);}
 static void release(){if(held!=null)w.getChunkSource().removeRegionTicket(TICKET,held,0,269L);held=null;}
 static void tick(){try{current="paired_frequency_native";if(System.nanoTime()-began>720_000_000_000L)throw new IllegalStateException("12min frequency bound");
 if(phase==0){if(pending==null){if(index==300||System.nanoTime()-began>120_000_000_000L){phase=1;index=0;return;}int serial=index;pending=WORKER.submit(()->planCell(serial));pendingSince=System.nanoTime();return;}if(!pending.isDone()){if(System.nanoTime()-pendingSince>10_000_000_000L)throw new IllegalStateException("forecast did not cooperate with five-second budget");return;}var row=pending.get();pending=null;rows.add(row);Object value=row.get("accepted");if(value instanceof String selected&&!selected.equals("UNKNOWN_BUDGET")){String setName=(String)row.get("set");var xy=(List<?>)row.get("chunk");var at=new ChunkPos(((Number)xy.get(0)).intValue(),((Number)xy.get(1)).intValue());if(selected.endsWith(":kurgan_great")||!setName.equals("kurgan_small"))confirmations.put(selected+"/"+at.toLong(),at);}if(value!=null||index%30==0)System.out.println("FREQUENCY269_PLAN "+row);index++;return;}
 if(phase==1){int[][] offsets={{1,0},{-1,0},{0,1},{0,-1}};if(index==offsets.length){org.slavicmyths.worldgen.StructureCoverageService.clearFootprints();ChudRegionPlanner.clear();phase=2;index=0;return;}var g=w.getChunkSource().getGenerator();var at=new ChunkPos(offsets[index][0]*256,offsets[index][1]*256);var c=new Structure.GenerationContext(w.registryAccess(),g,g.getBiomeSource(),w.getChunkSource().randomState(),w.getStructureManager(),w.getSeed(),at,w,b->true);var selected=ChudRegionPlanner.select(c);var row=new LinkedHashMap<String,Object>();row.put("region",List.of(offsets[index][0],offsets[index][1]));row.put("accepted",selected.isPresent());if(selected.isPresent()){var s=selected.get();String name="slavicmyths:"+(s.city()!=null?"chud_city":"chud_abandoned");row.put("structure",name);row.put("owner",List.of(s.owner().x,s.owner().z));if(s.city()!=null)row.put("variant",s.city().variant);else row.put("kind",s.abandoned().kind.toString());confirmations.put(name+"/"+s.owner().toLong(),s.owner());}regions.add(row);System.out.println("FREQUENCY269_CHUD "+row);index++;return;}
 if(ci>=confirmations.size()){WORKER.shutdownNow();out.put("placement_cells",rows);out.put("chud_regions",regions);out.put("native_confirmations",nativeRows);out.put("unknown_budget_candidates",rows.stream().filter(r->"UNKNOWN_BUDGET".equals(r.get("accepted"))).count());out.put("unexamined_candidates",300-rows.size());out.put("census_status",rows.size()==300&&rows.stream().noneMatch(r->"UNKNOWN_BUDGET".equals(r.get("accepted")))?"COMPLETE":"PARTIAL_NO_DENSITY_CLAIM");out.put("method","Native ChunkGenerator.java weighted retry order mirrored; singleton sets consume no random draw. Placement exclusions applied. One seed per real server world. No density claim from raw weights.");finish(null);return;}
 var e=new ArrayList<>(confirmations.entrySet()).get(ci);String name=e.getKey().substring(0,e.getKey().indexOf('/'));if(held==null){held=e.getValue();waiting=System.nanoTime();w.getChunkSource().addRegionTicket(TICKET,held,0,269L);return;}var chunk=w.getChunkSource().getChunkNow(held.x,held.z);if(chunk==null){if(System.nanoTime()-waiting>180_000_000_000L)throw new IllegalStateException("native FULL wait "+e);return;}var structure=w.registryAccess().registryOrThrow(Registries.STRUCTURE).get(ResourceLocation.parse(name));var s=chunk.getAllStarts().get(structure);boolean ok=s!=null&&s.isValid();check(ok,"forecast matches actual FULL "+name+" "+held);var row=new LinkedHashMap<String,Object>();row.put("structure",name);row.put("chunk",List.of(held.x,held.z));row.put("valid_native_start",ok);row.put("block_entity_count",chunk.getBlockEntities().size());if(ok){var b=s.getBoundingBox();row.put("bounds",List.of(b.minX(),b.minY(),b.minZ(),b.maxX(),b.maxY(),b.maxZ()));for(var piece:s.getPieces()){if(piece instanceof ChudPiece city)row.put("city_variant",city.plan.variant);if(piece instanceof AbandonedPiece abandoned)row.put("abandoned_kind",abandoned.plan.kind.toString());}}nativeRows.add(row);System.out.println("FREQUENCY269_NATIVE "+row);release();ci++;
 }catch(Throwable ex){WORKER.shutdownNow();release();out.put("placement_cells",rows);out.put("native_confirmations",nativeRows);out.put("chud_regions",regions);finish(ex);}}
}
